    unordered_set<char> st;
    // traverse the string once and store the  characters
    for (int i = 0; i < str.length(); i++)
        st.insert(str[i]);
    // number of unique characters
    int unique = st.size();
      unordered_map<char, int> mp;
    // to store the result
    int res = INT_MAX;
    int j = 0; // starting index of window
